// Creation order of code layers, the tab bar is sorted by it
static int code_layer_counter = 0;

Layer* new_layer_code(){
    Layer* code = malloc(sizeof(Layer));
    if(!code){
        return NULL;
    }
    code->type = LAYER_CODE;
    code->consume_input = true;
    code->draws_fullscreen = true;
    code->handle_keypress_function = &layer_code_handle_keypress;
    code->update_function = &layer_code_update;

    LayerCodeData* lcd = calloc(1, sizeof(LayerCodeData));
    if(!lcd){
        free(code);
        return NULL;
    }
    lcd->allow_diagnostics = true;
    lcd->cursor = calloc(1, sizeof(Cursor));
    if(!lcd->cursor){
        free(code);
        free(lcd);
        return NULL;
    }
    lcd->select_end = NULL;

    lcd->finding_substr = NULL;
    lcd->virtual_window = NULL;

    lcd->filename = NULL;
    for(size_t i = 0; i < default_filename_length; i++){
        arrput(lcd->filename, default_filename[i]);
    }
    arrput(lcd->filename, '\0');
    lcd->code_buffer = NULL;
    lcd->saved = true;
    code->layer_data = lcd;

    // Tree-sitter
    lcd->parser = NULL;
    lcd->tree = NULL;
    lcd->lang = LANG_UNKNOWN;
    lcd->query = NULL;

    // LSP
    lcd->uri = NULL;
    lcd->version = 1;
    lcd->id = random_id();
    lcd->diagnostics = NULL;
    lcd->ranges = NULL;
    lcd->completion_window = NULL;
    lcd->completion_function_params = NULL;
    lcd->pending_edit = false;

    // Editing
    lcd->undo_stack = NULL;
    lcd->redo_stack = NULL;
    lcd->undo_group = 0;
    lcd->saved_undo_len = 0;
    lcd->undo_replaying = false;
    lcd->typing_run = false;
    lcd->crlf = false;
    CCodeConfig* cfg = view_config();
    lcd->use_tabs = cfg ? cfg->use_tabs : false;
    lcd->read_only = false;
    lcd->preferred_col = -1;
    lcd->mtime = 0;

    lcd->tab_order = ++code_layer_counter;
    lcd->is_welcome = false;
    lcd->last_cx = -1;
    lcd->last_cy = -1;
    lcd->final_newline = true;
    return code;
}


static char* layer_code_center_text_in_buffer(const char* buffer, int w){
    size_t buffer_len = strlen(buffer);
    char* centered_text = NULL;
    int offset = w-buffer_len;

    for(int i = 0; i < offset/2; i++){
        arrput(centered_text, ' ');
    }
    while(*buffer){
        arrput(centered_text, *buffer);
        buffer++;
    }
    arrput(centered_text, '\n');
    arrput(centered_text, '\0');
    return centered_text;
}

static char* layer_code_left_allign_text_in_buffer(const char* buffer, int left_pad, int w){
    (void) w;
    char* left_allign = NULL;
    for(int i = 0; i < left_pad; i++){
        arrput(left_allign, ' ');
    }
    while(*buffer){
        arrput(left_allign, *buffer);
        buffer++;
    }
    arrput(left_allign, '\n');
    arrput(left_allign, '\0');
    return left_allign;
}


